class relatorios():
    def printcliente(self):
        webbrowser.open(r'C:\Users\EPIC!-PC\Documents\GitHub\DelovperPython\clientes.pdf')
    def gerarrelcliente(self):
        self.c = canvas.Canvas('clientes.pdf')
        self.codigorel = self.codeinput.get()
        self.nomerel = self.nomeinput.get()
        self.telerel = self.teleinput.get()
        self.cidaderel = self.cidadeinput.get()
        self.c.setFont('Helvetica-Bold', 24)
        self.c.drawString(200, 790, 'Ficha do Cliente')

        self.c.setFont('Helvetica-Bold', 12)
        self.c.drawString(50, 700, 'Código: ' + self.codigorel)
        self.c.drawString(50, 670, 'Nome: ' + self.nomerel)
        self.c.drawString(50, 640, 'Telefone: ' + self.telerel)
        self.c.drawString(50, 610, 'Cidade: ' + self.cidaderel)

        self.c.rect(20, 550, 550, 5, fill=True, stroke=True)

        self.c.showPage()
        self.c.save()
        self.printcliente()


class funcoes():
    def limpartela(self):
        self.codeinput.delete(0, END)
        self.nomeinput.delete(0, END)
        self.teleinput.delete(0, END)
        self.cidadeinput.delete(0, END)
    def sqlconect(self):
        self.conn = sqlite3.connect('Clientes.db'); print('Conectando ao banco de dados')
        self.cursor = self.conn.cursor()
    def sqldesconect(self):
        self.conn.close()
    def listaclientes(self):
        self.sqlconect(); print("Conectando Banco de Dados")
        ###Tabela
        self.cursor.execute("""
            CREATE TABLE IF NOT EXISTS clientes (
                cod INTEGER PRIMARY KEY,
                nomecliente CHAR(40) NOT NULL,
                telefone INTEGER(20),
                cidade INTEGER(40)
            );
            """)
        self.conn.commit(); print('Banco de dados Criado')
        self.sqldesconect() 
    def addcliente(self):
        self.codigo = self.codeinput.get()
        self.nome = self.nomeinput.get()
        self.telefone = self.teleinput.get()
        self.cidade = self.cidadeinput.get()
        #sql
        self.sqlconect()
        self.cursor.execute(""" INSERT INTO Clientes (nomecliente, telefone, cidade)
                            VALUES (?, ?, ?)""", (self.nome, self.telefone, self.cidade))
        self.conn.commit()
        self.selecionarlista()
        self.sqldesconect()
    def variaveis(self):
        self.codigo = self.codeinput.get()
        self.nome = self.nomeinput.get()
        self.telefone = self.teleinput.get()
        self.cidade = self.cidadeinput.get()
    def selecionarlista(self):
        self.list.delete(*self.list.get_children())
        self.sqlconect()
        listaa = self.cursor.execute(""" SELECT cod, nomecliente, telefone, cidade FROM Clientes
                                     ORDER BY nomecliente ASC; """)
        for i in listaa:
            self.list.insert("", END, values=i)
        self.sqldesconect()
        self.limpartela()                       
    def cliqueduplo(self, event):
        self.limpartela()
        self.list.selection()
        for n in self.list.selection():
            col1, col2, col3, col4 = self.list.item(n, 'values')
            self.codeinput.insert(END, col1)
            self.nomeinput.insert(END, col2)
            self.teleinput.insert(END, col3)
            self.cidadeinput.insert(END, col4)
    def deletarcliente(self):
        self.variaveis()
        self.sqlconect()
        self.cursor.execute("""DELETE FROM Clientes WHERE COD = ?""", (self.codigo))
        self.conn.commit()
        self.sqldesconect()
        self.limpartela()
        self.selecionarlista()
    def alterarcliente(self):
        self.variaveis()
        self.sqlconect()
        self.cursor.execute("""UPDATE Clientes SET nomecliente = ?, telefone = ?, cidade = ?
                            WHERE cod = ?""", (self.nome, self.telefone, self.cidade, self.codigo))
        self.conn.commit()
        self.sqldesconect()
        self.selecionarlista()
        self.limpartela()
    def buscacliente(self):
        self.sqlconect()
        self.list.delete(*self.list.get_children())

        self.nomeinput.insert(END, '%')
        nome = self.nomeinput.get()
        self.cursor.execute(
            """SELECT cod, nomecliente, telefone, cidade FROM Clientes
            WHERE nomecliente LIKE '%s' ORDER BY nomecliente ASC""" %nome)
        buscarcliente = self.cursor.fetchall()
        for i in buscarcliente:
            self.list.insert("", END, values=i)
        self.limpartela()
        self.sqldesconect()
    def imagens64(self):
        self.btnovob64 = '' 

